        ok: true,
        json: async () => ({
          cargado: false,
          pid: null,
          ultimasLineas: [],
          medidoEn: new Date().toISOString()
        })
      } as Response;
    };

    render(<TunelMetaGenesisEstado />);
    await screen.findByText(/Túnel de MetaGenesis: parado/i);
    expect(screen.queryByText(/Últimas líneas:/i)).not.toBeInTheDocument();
  });

